def comb_sort(nums):
    gap = len(nums)
    swapped = True
    while gap > 1 or swapped:
        gap = max(1, gap // 1.3)  # Shrinking gap
        swapped = False
        for i in range(len(nums) - gap):
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                swapped = True
    return nums
```

```python
def comb_sort(nums):
    if not nums:
        return nums

    n = len(nums)
    gap = n
    shrink = 1.3
    sorted_flag = False

    while not sorted_flag:
        gap = int(gap / shrink)
        if gap < 1:
            gap = 1
        sorted_flag = True

        for i in range(n - gap):
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                sorted_flag = False

    return nums
```

