def find_kth(arr1, arr2, k):
    if len(arr1) > len(arr2):
        return find_kth(arr2, arr1, k)

    if len(arr1) == 0:
        return arr2[k]

    if k == 0:
        return min(arr1[0], arr2[0])

    partition_size = min(len(arr1), k // 2)
    if arr1[partition_size - 1] <= arr2[k - partition_size]:
        left_part = arr1[:partition_size]
        right_part = arr1[partition_size:]
        arr1 = right_part
    else:
        left_part = arr2[:k - partition_size]
        right_part = arr2[k - partition_size:]
        arr2 = right_part

    return find_kth(arr1, arr2, k - partition_size)
