def reverse_Array_Upto_K(input, k):
    # Handle edge cases where k is larger than the array length or invalid
    if k <= 0 or k > len(input):
        return input.copy()

    # Slice the array up to k elements and reverse that slice
    reversed_part = input[:k][::-1]
    # Combine the reversed part with the remaining part of the array
    return reversed_part + input[k:]
